 </section>:tab==="nature"?<section className="atlas"><h3>Berge, Tiere, Wälder und Naturrekorde</h3><p>Die Punkte zeigen Beispiele. Eine Tierart oder ein Gebirge ist größer als ein einzelner Punkt.</p><div className="atlas-grid">{NATURE.slice(0,natureLimit).map(p=><article className="atlas-country" key={p.id}><h4>{p.name}</h4><NatureVisual place={p} onPlace={onPlace}/><p>{p.text}</p><details><summary>Noch mehr wissen</summary><p>{p.fact}</p></details>{NATURE_SOURCE_NOTES[p.id]&&<LearningDetails summary="Einordnung und Quellen"><GeographyNotes place={{...p,...NATURE_SOURCE_NOTES[p.id]}}/></LearningDetails>}<button className="secondary-button" onClick={()=>onPlace(p)}>Auf der Weltkugel finden</button><button className="speech-button" onClick={()=>onRead(p.name+'. '+p.text+' '+p.fact)}><Volume2 size={17}/> Vorlesen</button></article>)}</div>{NATURE.length>natureLimit&&<button className="secondary-button" onClick={()=>set("natureLimit",n=>n+24)}>Weitere Naturorte entdecken</button>}</section>:<div className="atlas"><section><h3><MapPin size={22}/> Länder & Hauptstädte</h3><p className="atlas-intro">Ein genauerer Blick auf {countries.filter(c=>countryPlace(c).capital).length} Länder. Weitere Länder und Gebiete findest du auf der Weltkugel.</p><div className="atlas-grid">{selectedCountries.slice(0,limit).map(p=><article className="atlas-country" key={p.id}><span className="category-pill">{CONTINENTS.find(c=>c.id===countries.find(c=>c.properties.id===p.id)?.properties.continent)?.name}</span><h4>{p.name}</h4><span className="atlas-capital">Hauptstadt: <strong>{p.capital}</strong></span><p>{p.text}</p><div className="atlas-fact">{p.fact}</div>{p.kind==="country"&&<CountryPortrait place={p} onRead={onRead}/>} {p.kind==="continent"&&<ContinentPortrait place={p}/>}<button className="secondary-button" onClick={()=>onPlace(p)}><Globe2 size={17}/> Auf dem Globus finden</button></article>)}</div>{selectedCountries.length>limit&&<button className="secondary-button atlas-more" onClick={()=>set("limit",n=>n+24)}>Weitere Länder entdecken ({selectedCountries.length-limit})</button>}{!selectedCountries.length&&<p className="empty-knowledge">Kein passendes Länderporträt. Du kannst trotzdem alle Länder und Gebiete auf der Weltkugel auswählen.</p>}</section>{!term&&<><section><h3><Compass size={22}/> Sieben Kontinente</h3><div className="atlas-grid">{CONTINENTS.map(p=><article className="atlas-country" key={p.id}><h4>{p.name}</h4><p>{p.text}</p><div className="atlas-fact">{p.fact}</div>{p.kind==="country"&&<CountryPortrait place={p} onRead={onRead}/>} {p.kind==="continent"&&<ContinentPortrait place={p}/>}<button className="secondary-button" onClick={()=>onPlace(p)}>Auf dem Globus finden</button></article>)}</div></section><section><h3><Waves size={22}/> Fünf Ozeane</h3><div className="atlas-grid">{OCEANS.slice(0,5).map(p=><article className="atlas-country" key={p.id}><h4>{p.name}</h4><p>{p.text}</p><div className="atlas-fact">{p.fact}</div>{p.kind==="country"&&<CountryPortrait place={p} onRead={onRead}/>} {p.kind==="continent"&&<ContinentPortrait place={p}/>}<button className="secondary-button" onClick={()=>onPlace(p)}>Auf dem Globus finden</button></article>)}</div></section></>}</div>}</TabsContent></Tabs></section>;
