function WordConnection({name,onJourney,onTopic}:{name:string;onJourney?:(id:string)=>void;onTopic?:(id:string)=>void}){const target=name==='Schwerkraft'?'science-tides':name==='Umlaufbahn'?'invention-satellite':undefined;return <div className="word-connections"><BookRelatedWords term={name}/>{WORD_ROUTES[name]&&<button data-route-focus={'book-word-'+name+'-journey'} className="knowledge-link" onClick={()=>onJourney?.(WORD_ROUTES[name])}>In einer Lernreise ausprobieren →</button>}{target&&<button data-route-focus={'book-word-'+name+'-topic'} className="knowledge-link" onClick={()=>onTopic?.(target)}>{name==='Schwerkraft'?'Wie Anziehung das Meer bewegt →':'Eine passende Entdeckerkarte →'}</button>}</div>;}
function NatureVisual({place,onPlace}:{place:Place;onPlace:(p:Place)=>void}){const ids:Record<string,string>={'polar-bear':'polar-bear','penguin':'emperor-penguin','giraffe':'giraffe','panda':'giant-panda','kangaroo':'red-kangaroo'},image=ids[place.id];return image?<WorldPhoto id={image} compact/>:<TopicMap compact entry={{id:place.id,category:'science',title:place.name,intro:place.text,aliases:[],locations:[{label:place.name,lat:place.lat,lon:place.lon}]}} onPlace={()=>onPlace(place)}/>;}
